---@type PayActivityConfig
local PayActivityConfig = T(Global, "PayActivityConfig")

---@param player SBasePlayer
function GMHelper:printPlayerPayActivity(player)
    player.payActivity:print()
end

---@param player SBasePlayer
function GMHelper:resetPlayerPayActivity(player)
    for _, activity in pairs(player.payActivity.activities) do
        activity:initDataInfo()
    end
end

function GMHelper:startAllPayActivity()
    local cfgs = PayActivityConfig:getAllCfgs()
    for _, cfg in pairs(cfgs) do
        if cfg.startDate > os.time() then
            cfg.startDate = os.time()
        end
    end
end

function GMHelper:payActivityRoundTest(player)
    LuaTimer:scheduleTimer(function ()
        local str= PayActivityConfig.loadActivityRoundCfg and "轮换服务端lua已更新" or "未找到轮换服务端lua接口"
        player:sendPacket({
            pid = "onShowToast",
            strKey = str,
        })
    end,1000,1)
end

function GMHelper:payActivityRoundCfgTest(player)
    LuaTimer:scheduleTimer(function ()
        local str= PayActivityConfig.roundsCfg and "服务端配置表PayActivityRounds.csv已更新"
                or "未找到服务端配置表PayActivityRounds.csv"
        player:sendPacket({
            pid = "onShowToast",
            strKey = str,
        })
    end,1000,1)
end

function GMHelper:hideTimeUITest(player)
    LuaTimer:scheduleTimer(function ()
        local str= "服务端："
        local str2= ""
        local cfg=PayActivityConfig:getAllCfgs()
        for i, v in pairs(cfg) do
            str=str.."_"..v.hideTimeUI
            str2=str2.."__"..os.date("%y.%m.%d",v.endDate)
        end
        str=str.."=="..str2
        player:sendPacket({
            pid = "onShowToast",
            strKey = str,
        })
    end,2000,1)
end

function GMHelper:watchAd(player, type, params)
    CEvents.WatchAdvertFinishedEvent:invoke(player.rakssid, type, params, 1)
end